import test from 'node:test';
import assert from 'node:assert/strict';
import {testServer} from './helpers.js';
async function scenario(fn) {
  const server=await testServer();
  try {
    const owner=server.agent();
    await owner('POST','/auth/signup',{name:'Audit owner',email:'audit-owner@example.test',password:'permission audit password'});
    const org=(await owner('POST','/orgs',{name:'Audit organization'})).data.organization;
    const project=(await owner('POST','/orgs/'+org.id+'/projects',{key:'AUD',name:'Audit project'})).data.project;
    const issue=(await owner('POST','/projects/'+project.id+'/issues',{title:'Audit issue'})).data.issue;
    const target=(await owner('POST','/projects/'+project.id+'/issues',{title:'Audit target'})).data.issue;
    const label=(await owner('POST','/projects/'+project.id+'/labels',{name:'Audit label'})).data.label;
    const comment=(await owner('POST','/issues/'+issue.id+'/comments',{body:'Audit comment'})).data.comment;
    const relation=(await owner('POST','/issues/'+issue.id+'/relations',{kind:'blocks',targetIssueId:target.id})).data.relation;
    const routes=[
      ['GET','/projects/'+project.id+'/assignees'],
      ['GET','/projects/'+project.id+'/issues'],
      ['GET','/orgs/'+org.id+'/issues'],
      ['POST','/projects/'+project.id+'/issues',{title:'Denied'}],
      ['GET','/issues/'+issue.id],
      ['PATCH','/issues/'+issue.id,{title:'Denied'}],
      ['DELETE','/issues/'+issue.id],
      ['GET','/projects/'+project.id+'/labels'],
      ['POST','/projects/'+project.id+'/labels',{name:'Denied'}],
      ['PATCH','/labels/'+label.id,{name:'Denied'}],
      ['DELETE','/labels/'+label.id],
      ['GET','/issues/'+issue.id+'/comments'],
      ['POST','/issues/'+issue.id+'/comments',{body:'Denied'}],
      ['PATCH','/comments/'+comment.id,{body:'Denied'}],
      ['DELETE','/comments/'+comment.id],
      ['GET','/issues/'+issue.id+'/relations'],
      ['POST','/issues/'+issue.id+'/relations',{kind:'relates',targetIssueId:target.id}],
      ['DELETE','/relations/'+relation.id]
    ];
    await fn({server,owner,org,project,issue,target,label,comment,relation,routes});
  }finally{await server.close();}
}
test('all issue label comment relation and candidate routes reject anonymous and unrelated accounts',()=>scenario(async({server,owner,issue,routes})=>{
  const anonymous=server.agent(),outsider=server.agent();
  await outsider('POST','/auth/signup',{name:'Unrelated',email:'unrelated@example.test',password:'permission audit password'});
  for(const [method,path,body] of routes){
    assert.equal((await anonymous(method,path,body)).status,401,'anonymous '+method+' '+path);
    assert.equal((await outsider(method,path,body)).status,403,'outsider '+method+' '+path);
  }
  assert.equal((await owner('GET','/issues/'+issue.id)).data.issue.title,'Audit issue');
  assert.equal((await owner('GET','/issues/'+issue.id+'/comments')).data.items[0].body,'Audit comment');
}));
test('granted guest access permits reads and own comments while every issue mutation stays denied',()=>scenario(async({server,owner,org,project,issue,routes})=>{
  const guest=server.agent();const signup=await guest('POST','/auth/signup',{name:'Granted Guest',email:'granted@example.test',password:'permission audit password'});
  await owner('POST','/orgs/'+org.id+'/members',{userId:signup.data.user.id,role:'guest'});
  await owner('POST','/projects/'+project.id+'/guests',{userId:signup.data.user.id});
  for(const [method,path,body] of routes){
    if(method==='GET')assert.equal((await guest(method,path,body)).status,200,'guest read '+path);
    else if(path.endsWith('/comments')&&method==='POST')continue;
    else assert.equal((await guest(method,path,body)).status,403,'guest mutation '+method+' '+path);
  }
  const created=await guest('POST','/issues/'+issue.id+'/comments',{body:'Guest can discuss'});assert.equal(created.status,201);
  assert.equal((await guest('PATCH','/comments/'+created.data.comment.id,{body:'Guest edited'})).status,200);
  assert.equal((await guest('DELETE','/comments/'+created.data.comment.id)).status,200);
}));
